import type { Plugin } from "../../kernel/types";

const plugin = {
  id: "pricing",
  name: "Pricing",
  version: "1.0.0",
  onLoad(ctx: import("../../kernel/types").PluginContext) {
    // 注册 service: id=pricing，实例提供 total(n) = n*21
    ctx.register({
      kind: "service",
      service: {
        id: "pricing",
        value: {
          total(n: number): number {
            return n * 21;
          },
        },
      },
    });

    // 注册工具 quote_total：通过 ctx.inject("service:pricing").value 使用该服务
    ctx.register({
      kind: "tool",
      tool: {
        name: "quote_total",
        version: "1.0.0",
        description: "调用 pricing 服务的 total(n)，返回 n*21 的报价总额。",
        permissions: {
          capabilities: ["service:pricing"],
        },
        sideEffect: "none",
        parameters: {
          type: "object",
          properties: {
            n: { type: "number", description: "数量，计算 total = n * 21" },
          },
          required: ["n"],
        },
        outputSchema: {
          type: "object",
          properties: {
            ok: { type: "boolean" },
            data: {
              type: "object",
              properties: {
                total: { type: "number" },
              },
              required: ["total"],
            },
          },
          required: ["ok", "data"],
        },
        async handler(args: { n?: number }, _tctx: unknown) {
          const n = Number(args?.n);
          if (!Number.isFinite(n)) {
            return { ok: false as const, error: "参数 n 必须是有效数字" };
          }
          const svc = ctx.inject("service:pricing");
          const total = svc.value.total(n);
          return { ok: true as const, data: { total } };
        },
      },
    });
  },
};

export default plugin as Plugin;

